onChange.script:
if origin == 'BindingWriteback':
	startDate = self.custom.values.startDate
	cutoffDate = system.date.setTime(self.custom.ends.cutoffDate, 23, 59, 59)
	vals = self.custom.rruleParams
	ends = self.custom.ends.selection
	count = self.custom.ends.count or 1
	untilDate = None
	if cutoffDate is None: pass
	elif ends == 'on': untilDate = system.kanoa.utilities.javaDateToPython(cutoffDate).strftime('%Y%m%dT%H%M%S')
	elif ends == 'after':
		if vals['FREQ'] == 'DAILY': untilDate = system.date.addDays(startDate, count)
		elif vals['FREQ'] == 'WEEKLY': untilDate = system.date.addWeeks(startDate, count)
		elif vals['FREQ'] == 'MONTHLY': untilDate = system.date.addMonths(startDate, count)
		elif vals['FREQ'] == 'YEARLY': untilDate = system.date.addYears(startDate, count)

		untilDate = system.date.midnight(untilDate)
		untilDate = system.kanoa.utilities.javaDateToPython(untilDate).strftime('%Y%m%dT%H%M%S')

	vals['UNTIL'] = untilDate

return

transforms.code:
rruleParams = {"FREQ": "WEEKLY", "INTERVAL": 1, "BYWEEKDAY": None, "BYMONTHDAY": None, "UNTIL": None, "monthly": None}

weekDays = {'MO': False, 'TU': False, 'WE': False, 'TH': False, 'FR': False, 'SA': False, 'SU': False}
weekdayMap = {'1': 'SU', '2': 'MO', '3': 'TU', '4': 'WE', '5': 'TH', '6': 'FR', '7': 'SA'}
weekdayList = ['MO', 'TU', 'WE', 'TH', 'FR', 'SA', 'SU']

rruleStr = self.view.params.values.rruleStr
startDate = self.view.params.values.startDate
dayOfWeek = str(system.date.getDayOfWeek(startDate)) if startDate else '1'

# Parse RRULE only if present
if rruleStr and str(rruleStr).strip():
	for rruleSection in str(rruleStr).split(";"):
		if "=" in rruleSection:
			k, v = rruleSection.split("=", 1)
			rruleParams[k] = v

# Apply defaults only after parsing
if rruleParams['FREQ'] == 'MONTHLY':
	if rruleParams["BYMONTHDAY"]:
		rruleParams['monthly'] = system.util.jsonEncode({
			"dayOfMonth": int(rruleParams["BYMONTHDAY"]),
			"choice": "nth day of month"
		})
	elif rruleParams["BYWEEKDAY"]:
		# Expected format like TU(2)
		byWeekDaySplit = rruleParams["BYWEEKDAY"].split("(")
		if len(byWeekDaySplit) == 2:
			dayCode = byWeekDaySplit[0]
			weekOfMonth = int(byWeekDaySplit[1][:-1])

			dayOfWeekNum = None
			for k, v in weekdayMap.items():
				if v == dayCode:
					dayOfWeekNum = int(k)
					break

			if dayOfWeekNum is not None:
				rruleParams['monthly'] = system.util.jsonEncode({
					"weekOfMonth": weekOfMonth,
					"dayOfWeek": dayOfWeekNum,
					"choice": "nth weekday of month"
				})

elif rruleParams['FREQ'] == 'WEEKLY':
	# If RRULE did not specify a weekday, default to startDate weekday
	if not rruleParams['BYWEEKDAY']:
		rruleParams['BYWEEKDAY'] = weekdayMap[dayOfWeek]

# Ends handling
if rruleParams.get("UNTIL"):
	self.custom.ends.selection = 'on'
	assetInfo = system.kanoa.utilities.convertDatasetRowToJSON(
		system.kanoa.asset.getAssets({'assetPath': value['assetPath']}),
		0
	)
	cutoffDate = system.date.parse(rruleParams['UNTIL'], "yyyyMMdd'T'HHmmss")
	tzOffsetMins = system.kanoa.date.getTimeZoneOffsetMins(assetInfo['timeZone'], cutoffDate)
	self.custom.ends.cutoffDate = system.date.addMinutes(cutoffDate, -tzOffsetMins)
else:
	self.custom.ends.selection = 'never'

# Initialize weekday selector from parsed/defaulted rruleParams only
byWeekDay = rruleParams['BYWEEKDAY']
selectedWeekdays = byWeekDay.split(",") if byWeekDay else []

for weekday in weekdayList:
	if rruleParams['FREQ'] == 'WEEKLY' and weekday in selectedWeekdays:
		weekDays[weekday] = True

self.custom.weekdays = weekDays

return rruleParams

onChange.script:
if origin in ('BindingWriteback', 'Script'):
	vals = self.custom.rruleParams
	rruleStr = 'FREQ=' + str(vals['FREQ']) + ';INTERVAL=' + str(vals['INTERVAL'])

	if vals['FREQ'] == 'WEEKLY' and vals['BYWEEKDAY']: rruleStr += ';BYWEEKDAY=' + vals['BYWEEKDAY']
	elif vals['FREQ'] == 'MONTHLY' and vals['monthly']:
		monthly = system.util.jsonDecode(vals['monthly'])
		if monthly['choice'] == 'nth day of month':
			rruleStr += ';BYMONTHDAY=' + str(monthly['dayOfMonth'])
		elif monthly['choice'] == 'nth weekday of month':
			weekdayAbbrevs = {'1': 'SU', '2': 'MO', '3': 'TU', '4': 'WE', '5': 'TH', '6': 'FR', '7': 'SA'}
			weekOfMonth = str(monthly['weekOfMonth'])
			dayOfWeek = str(monthly['dayOfWeek'])
			byWeekDay = weekdayAbbrevs[dayOfWeek] + "(" + weekOfMonth + ")"
			rruleStr += ';BYWEEKDAY=' + byWeekDay

	if self.custom.rruleParams['UNTIL']: 	rruleStr += ';UNTIL=' + (vals['UNTIL'] or '')

	self.custom.values.rruleStr = rruleStr

	return

